#include <iostream>
#include <vector>
using namespace std;

int main() {
    while (true) {
        int n;
        cin >> n;
        if (n == 0)
            break;

        vector<int> dp(n + 1, 0); // Use vector for dynamic allocation
        dp[0] = 1; // Base case

        for (int i = 1; i <= n; ++i) {
            dp[i] += dp[i - 1]; // Ways to reach i-1
            if (i >= 2) dp[i] += dp[i - 2]; // Ways to reach i-2
            if (i >= 3) dp[i] += dp[i - 3]; // Ways to reach i-3
        }

        int ans = dp[n];
        ans = (ans + 3649) / 3650; // Optimize the division and modulus operation

        cout << ans << endl;
    }
}

