        if (n == 0)
            break;

        int a = 1, b = 0, c = 0; // Base cases for dp[0], dp[1], dp[2]

        for (int i = 1; i <= n; ++i) {
            int current = a; // Current state corresponds to dp[i-1]
            if (i >= 2) current += b; // Update current based on dp[i-2]
            if (i >= 3) current += c; // Update current based on dp[i-3]

            // Shift states for the next iteration
            c = b; // dp[i-3] becomes dp[i-2]
            b = a; // dp[i-2] becomes dp[i-1]
            a = current; // current result becomes dp[i]
        }

        printf("%d\n", (a / 3650) + (a % 3650 != 0)); // Output the result with proper formatting
    }
}

